import constellationCatalogData from './data/constellationCatalog.json'
import type { ConstellationRecord } from './constellationTypes'

/**
 * Validates a single record's shape at load time. The build script
 * (scripts/build-constellation-catalog.mjs) already validates when
 * generating the bundled JSON, but CLAUDE.md's Security Baseline calls for
 * validating external data where it's consumed too, in case the committed
 * file is ever hand-edited, regenerated by a modified script, or otherwise
 * corrupted.
 */
function isValidConstellationRecord(
  record: unknown,
): record is ConstellationRecord {
  if (typeof record !== 'object' || record === null) return false
  const { id, name, nameJa, segments } = record as Record<string, unknown>

  if (typeof id !== 'string' || id.length === 0) return false
  if (typeof name !== 'string' || name.length === 0) return false
  if (typeof nameJa !== 'string' || nameJa.length === 0) return false
  if (!Array.isArray(segments)) return false

  return segments.every(
    (segment) =>
      Array.isArray(segment) &&
      segment.length === 2 &&
      segment.every(
        (starId) => typeof starId === 'number' && Number.isFinite(starId),
      ),
  )
}

let cachedCatalog: ConstellationRecord[] | null = null

/** Loads the pre-matched constellation line/name catalog (see DECISIONS.md D015). */
export function loadConstellationCatalog(): ConstellationRecord[] {
  if (cachedCatalog === null) {
    cachedCatalog = (constellationCatalogData as unknown[]).filter(
      isValidConstellationRecord,
    )
  }
  return cachedCatalog
}

/**
 * Finds the constellation a HYG star id belongs to (Task 5: showing "所属星座"
 * for a tap/click-selected star), by checking segment membership. Most stars
 * aren't part of any constellation's line figure and resolve to null. A star
 * shared between two constellations' segments (not expected in this dataset,
 * but not structurally impossible) resolves to whichever is found first.
 */
export function findConstellationByStarId(
  hygStarId: number,
): ConstellationRecord | null {
  for (const constellation of loadConstellationCatalog()) {
    for (const [startId, endId] of constellation.segments) {
      if (startId === hygStarId || endId === hygStarId) return constellation
    }
  }
  return null
}
